public void RecoverTree(TreeNode? root)
{
    TreeNode? prev = null;
    TreeNode? first = null, second = null;
    Inorder(root);
    (first.Val, second.Val) = (second.Val, first.Val);

    void Inorder(TreeNode? node)
    {
        if (node == null) return;
        Inorder(node.Left);
        if (prev != null && prev.Val > node.Val)
        {
            if (first == null) first = prev;
            second = node;
        }
        prev = node;
        Inorder(node.Right);
    }
}
